	if !w.dynamicRoutes {
		return fmt.Errorf("dynamic routes are not enabled.")
	}
	w.routesLock.Lock()
	defer w.routesLock.Unlock()
	for ix := range w.routes {
		if w.routes[ix].Method == method && w.routes[ix].Path == path {
			w.routes = append(w.routes[:ix], w.routes[ix+1:]...)
