func trace(what string, delta int) {
	indented := what
	if delta < 0 {
		indentLevel += delta
	}
	for t := 0; t < indentLevel; t++ {
		indented = "." + indented
	}
	log.Printf("%s", indented)
	if delta > 0 {
		indentLevel += delta
	}
}

